const {chromium}=require('playwright'),fs=require('fs'),os=require('os'),path=require('path'),http=require('http'),assert=require('assert/strict'),{execFileSync}=require('child_process');
const repo=path.resolve(__dirname,'../..'),dir=fs.mkdtempSync(path.join(os.tmpdir(),'sambaadm-dns-'));
execFileSync('go',['test','./internal/web','-run','^TestWorkspaceBrowserFixtures$','-count=1'],{cwd:repo,env:{...process.env,SAMBAADM_WEB_FIXTURE_DIR:dir}});
const server=http.createServer((req,res)=>{const p=new URL(req.url,'http://localhost').pathname,file=p.startsWith('/static/')?path.join(repo,'internal/web',p):path.join(dir,'admin-dns_routing.html');if(!fs.existsSync(file)){res.writeHead(404).end();return;}res.setHeader('Content-Type',file.endsWith('.js')?'application/javascript':file.endsWith('.css')?'text/css':'text/html');res.end(fs.readFileSync(file));});
(async()=>{await new Promise(r=>server.listen(0,'127.0.0.1',r));const browser=await chromium.launch({headless:true});try{
const page=await browser.newPage({viewport:{width:1280,height:900}}),errors=[],writes=[],plans=[];page.on('pageerror',e=>errors.push(e.message));let blocked=true;
await page.route('**/api/v1/**',async route=>{const request=route.request(),u=new URL(request.url()),p=u.pathname.slice(7),node=u.searchParams.get('node'),body=request.postDataJSON();let json=[],status=200;
 if(p==='/dns/zones')json=[{name:'ipr.loc'}];else if(p==='/dns/routing/nodes')json=['dc1.ipr.loc','dc2.ipr.loc'];
 else if(p.endsWith('/delegations/plan')){plans.push(body);json={domain:'app.ipr.loc',revision:'old',proposedRevision:'new',changes:[{name:'app',type:'NS',data:'ns.app.ipr.loc'}],warning:'NS и glue реплицируются через AD.'};}
 else if(p.endsWith('/delegations')){if(request.method()==='PUT')writes.push({p,body});json={delegations:[],revision:'old'};}
 else if(p==='/dns/forwarding'&&request.method()==='GET')json={editable:true,path:'/etc/bind/named.conf',revision:'r',rules:[{domain:node==='dc1.ipr.loc'?'keep-one.test':'keep-two.test',servers:['192.0.2.1'],mode:'only'}]};
 else if(p==='/dns/forwarding/plan'){if(node==='dc2.ipr.loc'&&blocked){await route.fulfill({status:409,json:{error:'BIND недоступен'}});return;}plans.push({node,body});json={revision:'r',proposedRevision:'next',before:'Старые правила',proposed:body.rules.map(r=>r.domain).join('\n')};}
 else if(p==='/dns/forwarding'&&request.method()==='PUT'){writes.push({node,body});json={backup:'/private/backup',status:{}};}
 else if(p==='/dns/backend/plan')json={backend:'BIND9_DLZ',target:body.target,revision:'backend-r',steps:['Остановить DNS и Samba','Проверить SOA и SRV'],warning:'Правила BIND сохраняются, но перестанут действовать.'};
 else if(p==='/dns/backend/start'){writes.push({p,body});json={id:'a'.repeat(32),state:'queued'};}
 else if(p==='/dns/backend/status')json={state:'completed',log:['<script>unsafe()</script>','Готово']};
 await route.fulfill({status,json});});
await page.goto('http://127.0.0.1:'+server.address().port+'/dns/routing');await page.getByLabel('Поддомен (например app)').fill('app');await page.getByLabel('DNS-серверы: имя и IP-адреса, по одному серверу в строке').fill('ns.app.ipr.loc 192.0.2.53');await page.getByRole('button',{name:'Предпросмотр',exact:true}).click();await page.getByText('Изменения: app.ipr.loc',{exact:true}).waitFor();assert.equal(writes.length,0);await page.getByLabel('Подтверждаю изменение делегирования').check();await page.getByRole('button',{name:'Применить',exact:true}).click();await page.getByText('Делегирование сохранено в AD-зоне.').waitFor();assert.equal(writes[0].body.confirm,true);
await page.getByRole('tab',{name:'Условная пересылка'}).click();await page.getByLabel('Домен пересылки (например app.ipr.loc)').fill('app.ipr.loc');await page.getByLabel('IP-адреса DNS-серверов через пробел').fill('192.0.2.53');await page.getByRole('button',{name:'Выбрать все'}).click();await page.getByRole('button',{name:'Предпросмотр',exact:true}).click();await page.getByText('Применение не запущено:',{exact:false}).waitFor();assert.equal(await page.getByRole('button',{name:'Применить на 2 серверах'}).count(),0);
blocked=false;await page.getByRole('button',{name:'Предпросмотр',exact:true}).click();await page.getByLabel('Подтверждаю применение на выбранных серверах').check();await page.getByRole('button',{name:'Применить на 2 серверах'}).click();await page.getByText('Обработка завершена.',{exact:false}).waitFor();const forwards=writes.filter(w=>w.node);assert.equal(forwards.length,2);assert(forwards[0].body.rules.some(r=>r.domain==='keep-one.test'));assert(forwards[1].body.rules.some(r=>r.domain==='keep-two.test'));assert(forwards.every(w=>w.body.rules.some(r=>r.domain==='app.ipr.loc')));
await page.getByRole('tab',{name:'DNS-бэкенд',exact:true}).click();await page.getByLabel('DNS-бэкенд',{exact:true}).selectOption('SAMBA_INTERNAL');await page.getByRole('button',{name:'Предпросмотр',exact:true}).click();await page.getByText('Правила BIND сохраняются, но перестанут действовать.').waitFor();assert.equal(writes.filter(w=>w.p==='/dns/backend/start').length,0);await page.getByLabel('Подтверждаю перезапуск DNS и Samba на этом DC').check();await page.getByRole('button',{name:'Начать',exact:true}).click();await page.getByText('Переключение DNS завершено.').waitFor();assert.equal(await page.locator('script').filter({hasText:'unsafe()'}).count(),0);
await page.setViewportSize({width:390,height:844});assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);assert.deepEqual(errors,[]);console.log('PASS DNS: delegation preview/confirmation, all-server preflight, per-node rule preservation, backend confirmation and escaped logs, mobile');
}finally{await browser.close();server.close();fs.rmSync(dir,{recursive:true,force:true});}})().catch(e=>{console.error(e);server.close();process.exitCode=1;});
